t.script:
(function () {
    var $ = function (id) { return document.getElementById(id); };
    var num = function (id) { var v = parseFloat(($(id).value || '0').replace(',', '.')); return isNaN(v) ? 0 : Math.max(0, v); };
    var fmt = function (n, d) { return n.toLocaleString('fr-BE', {minimumFractionDigits: d, maximumFractionDigits: d}); };
    var minuteur = null;

    function volume() {
        var forme = $('lp_forme').value;
        var prof = (num('lp_pmin') + num('lp_pmax')) / 2;
        var rond = forme === 'rond';
        document.querySelectorAll('.lp-dim-long, .lp-dim-larg').forEach(function (e) { e.classList.toggle('d-none', rond); });
        document.querySelector('.lp-dim-diam').classList.toggle('d-none', !rond);
        var L = num('lp_long'), l = num('lp_larg'), D = num('lp_diam');
        var surface = rond ? Math.PI * D * D / 4 : (forme === 'ovale' ? Math.PI * L * l / 4 : (forme === 'libre' ? L * l * 0.85 : L * l));
        return surface * prof;
    }

    function calculer() {
        var v = volume();
        $('lp_volume').textContent = fmt(v, 1);
        $('lp_litres').textContent = fmt(Math.round(v * 1000), 0);
        var kw = v / 4 * parseFloat($('lp_couv').value) * parseFloat($('lp_saison').value) * parseFloat($('lp_expo').value);
        kw = Math.max(3, Math.ceil(kw * 2) / 2);
        $('lp_kw').textContent = fmt(kw, 1);
        clearTimeout(minuteur);
        minuteur = setTimeout(function () { proposer(kw, v); }, 350);
    }

    function proposer(kw, v) {
        fetch('/calculateur-piscine/pac', {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {kw: kw, volume: v, triphase: $('lp_tri').value === '1'}})
        }).then(function (r) { return r.json(); }).then(function (r) {
            var modeles = (r.result || {}).modeles || [];
            var zone = $('lp_pac');
            zone.innerHTML = '';
            $('lp_pac_vide').classList.toggle('d-none', Boolean(modeles.length));
            modeles.forEach(function (m) {
                var col = document.createElement('div');
                col.className = 'col-6 col-md-4 col-lg-2';
                var a = document.createElement('a');
                a.className = 'lp-calc-pac'; a.href = m.url;
                var img = document.createElement('img'); img.src = m.image; img.alt = m.nom; img.loading = 'lazy';
                var t = document.createElement('div'); t.className = 'lp-calc-pac-nom'; t.textContent = m.nom;
                var d = document.createElement('div'); d.className = 'lp-calc-pac-detail';
                d.textContent = m.kw.toLocaleString('fr-BE') + ' kW' + (m.plage ? ' · ' + m.plage : '');
                var p = document.createElement('div'); p.className = 'lp-calc-pac-prix'; p.textContent = m.prix_txt;
                a.append(img, t, d, p); col.append(a); zone.append(col);
            });
        }).catch(function () {});
    }

    document.querySelectorAll('.lp-calc input, .lp-calc select').forEach(function (e) {
        e.addEventListener('input', calculer); e.addEventListener('change', calculer);
    });
    calculer();
})();
